/**
 * The built-in Quick Actions: support first, then start a discussion, write a
 * blog post, browse tags, recent activity and the marketplace, each only when
 * its extension (or permission) is there.
 */
function defaultQuickActions() {
  const support = supportTarget();
  const startDiscussion = e => {
    e.preventDefault();
    openComposer();
  };
  const links = [!!support && {
    icon: 'fa-solid fa-headset',
    label: ts('sidebar.qa_support_ticket'),
    href: support.href,
    route: support.route
  }, {
    icon: 'fa-solid fa-plus',
    label: ts('sidebar.qa_start_discussion'),
    href: app.route('index'),
    route: true,
    onclick: startDiscussion
  }, hasBlog() && app.forum.attribute('canCreateBlogPost') && {
    icon: 'fa-solid fa-pen-to-square',
    label: ts('sidebar.qa_write_blog'),
    href: app.route('linkrobins-blog.compose'),
    route: true
  }, 'flarum-tags' in flarum.extensions && {
    icon: 'fa-solid fa-tags',
    label: ts('sidebar.qa_browse_tags'),
    href: app.route('tags'),
    route: true
  }, {
    icon: 'fa-solid fa-clock',
    label: ts('sidebar.qa_recent_activity'),
    href: app.route('index'),
    route: true
  }, hasMarketplace() && {
    icon: 'fa-solid fa-store',
    label: ts('sidebar.qa_marketplace'),
    href: marketplaceUrl()
  }];
  return links.filter(link => !!link);
}
function initials(name) {
  const parts = String(name).trim().split(/\s+/);
  return (parts[0]?.[0] || '') + (parts[parts.length - 1]?.[0] || '');
}
flarum.reg.add('ernestdefoe-mosaic', 'forum/components/SidebarPanels', SidebarPanels);